import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { LayoutDashboard, FileCheck2, CreditCard, BookOpen, CalendarDays, Users, Wallet, Star, Flag, Tags, Settings as SettingsIcon, ScrollText, ShieldCheck, CheckCircle2, XCircle, AlertCircle, Download, Plus, Search, Eye, Check, X, RotateCcw, UserCog, UserMinus, UserPlus, PlayCircle, Sparkles, ExternalLink, TrendingUp, Banknote, Lock, Bell } from 'lucide-react';
import PanelShell from '../components/PanelShell.jsx';
import { useAuth } from '../context/AuthContext.jsx';
import { api } from '../lib/api.js';
import { Avatar, Badge, EmptyState, Field, LoadingRow, Modal, StatusBadge, useToast, Stars } from '../components/ui.jsx';
import { formatDate, formatDateTime, formatMT, formatNumber, formatTime, APPLICATION_LABELS, PAYMENT_LABELS, BOOKING_LABELS, LESSON_STATUS_LABELS } from '../lib/format.js';

export default function AdminPanel() {
  const { user } = useAuth(); const toast = useToast();
  const [tab, setTab] = useState('overview'); const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState(null); const [applications, setApplications] = useState([]); const [payments, setPayments] = useState([]); const [lessons, setLessons] = useState([]); const [bookings, setBookings] = useState([]); const [users, setUsers] = useState([]); const [withdrawals, setWithdrawals] = useState([]); const [reviews, setReviews] = useState([]); const [reports, setReports] = useState([]); const [subjects, setSubjects] = useState([]); const [levels, setLevels] = useState([]); const [settings, setSettings] = useState(null); const [audit, setAudit] = useState([]); const [team, setTeam] = useState([]);
  const [appFilter, setAppFilter] = useState('pending'); const [payFilter, setPayFilter] = useState('pending'); const [userQuery, setUserQuery] = useState(''); const [userRole, setUserRole] = useState('all'); const [userStatus, setUserStatus] = useState('all'); const [wdFilter, setWdFilter] = useState('all');
  const [appDetail, setAppDetail] = useState(null); const [rejectApp, setRejectApp] = useState(null); const [rejectReason, setRejectReason] = useState(''); const [busy, setBusy] = useState(false);
  const [confirmPay, setConfirmPay] = useState(null); const [payNote, setPayNote] = useState(''); const [attested, setAttested] = useState(false); const [rejectPay, setRejectPay] = useState(null); const [payReason, setPayReason] = useState(''); const [refundPay, setRefundPay] = useState(null); const [refundReason, setRefundReason] = useState('');
  const [cancelLesson, setCancelLesson] = useState(null); const [completeLesson, setCompleteLesson] = useState(null); const [suspendUser, setSuspendUser] = useState(null); const [suspendReason, setSuspendReason] = useState('');
  const [approveWd, setApproveWd] = useState(null); const [wdRef, setWdRef] = useState(''); const [rejectWd, setRejectWd] = useState(null); const [wdReason, setWdReason] = useState('');
  const [resolveReport, setResolveReport] = useState(null); const [reportNote, setReportNote] = useState('');
  const [settingsForm, setSettingsForm] = useState(null); const [settingsBusy, setSettingsBusy] = useState(false);
  const [newSubject, setNewSubject] = useState({ name: '', icon: 'BookOpen' }); const [newLevel, setNewLevel] = useState('');
  const [demoResult, setDemoResult] = useState(null); const [demoBusy, setDemoBusy] = useState(false); const [clearDemoOpen, setClearDemoOpen] = useState(false); const [demoClearBusy, setDemoClearBusy] = useState(false);
  const [promoteId, setPromoteId] = useState(''); const [teamBusy, setTeamBusy] = useState(false); const [notifForm, setNotifForm] = useState({ userId: '', title: '', body: '', link: '' }); const [notifBusy, setNotifBusy] = useState(false);
  const load = async () => {
    try {
      const [s, a, p, l, b, u, w, r, rep, sub, lvl, set, aud, tm] = await Promise.all([
        api('/admin/stats'), api('/admin/applications'), api('/admin/payments?status=all'), api('/admin/lessons'), api('/admin/bookings'), api('/admin/users'), api('/admin/withdrawals'), api('/admin/reviews'), api('/admin/reports'), api('/admin/subjects'), api('/admin/levels'), api('/admin/settings'), api('/admin/audit?limit=100'), api('/admin/team')
      ]);
      setStats(s); setApplications(a.applications || []); setPayments(p.payments || []); setLessons(l.lessons || []); setBookings(b.bookings || []); setUsers(u.users || []); setWithdrawals(w.withdrawals || []); setReviews(r.reviews || []); setReports(rep.reports || []); setSubjects(sub.subjects || []); setLevels(lvl.levels || []); setSettings(set.settings); setSettingsForm(set.settings); setAudit(aud.logs || []); setTeam(tm.team || []);
    } catch (e) { toast(e.message, 'error'); } finally { setLoading(false); }
  };
  useEffect(() => { load(); }, []);
  const run = async (fn, success) => { setBusy(true); try { await fn(); await load(); toast(success, 'success'); return true; } catch (e) { toast(e.message, 'error'); return false; } finally { setBusy(false); } };
  const approveApp = async (id) => { const ok = await run(() => api(`/admin/applications/${id}/approve`, { method: 'POST' }), 'Professor aprovado. Perfil publicado e papel atribuído.'); if (ok) setAppDetail(null); };
  const doRejectApp = async () => { const ok = await run(() => api(`/admin/applications/${rejectApp.id}/reject`, { method: 'POST', body: { reason: rejectReason } }), 'Candidatura rejeitada.'); if (ok) { setRejectApp(null); setRejectReason(''); setAppDetail(null); } };
  const confirmPayment = async () => { if (!attested) return toast('Confirma que verificaste a referência no extracto.', 'error'); const ok = await run(() => api(`/admin/payments/${confirmPay.id}/confirm`, { method: 'POST', body: { attested, note: payNote } }), 'Pagamento confirmado. Sala autorizada e carteira creditada.'); if (ok) { setConfirmPay(null); setAttested(false); setPayNote(''); } };
  const rejectPayment = async () => { const ok = await run(() => api(`/admin/payments/${rejectPay.id}/reject`, { method: 'POST', body: { reason: payReason } }), 'Pagamento rejeitado. O estudante foi notificado.'); if (ok) { setRejectPay(null); setPayReason(''); } };
  const refundPayment = async () => { const ok = await run(() => api(`/admin/payments/${refundPay.id}/refund`, { method: 'POST', body: { reason: refundReason } }), 'Reembolso registado e carteira do professor ajustada.'); if (ok) { setRefundPay(null); setRefundReason(''); } };
  const doCancelLesson = async () => { const ok = await run(() => api(`/admin/lessons/${cancelLesson.id}/cancel`, { method: 'POST', body: { reason: 'Cancelada pela administração.' } }), 'Aula cancelada.'); if (ok) setCancelLesson(null); };
  const doCompleteLesson = async () => { const ok = await run(() => api(`/admin/lessons/${completeLesson.id}/complete`, { method: 'POST' }), 'Aula concluída.'); if (ok) setCompleteLesson(null); };
  const suspend = async () => { const ok = await run(() => api(`/admin/users/${suspendUser.id}/suspend`, { method: 'POST', body: { reason: suspendReason } }), 'Conta suspensa.'); if (ok) { setSuspendUser(null); setSuspendReason(''); } };
  const reactivate = (id) => run(() => api(`/admin/users/${id}/reactivate`, { method: 'POST' }), 'Conta reactivada.');
  const approveWithdrawal = async () => { const ok = await run(() => api(`/admin/withdrawals/${approveWd.id}/approve`, { method: 'POST', body: { reference: wdRef } }), 'Levantamento aprovado e registado.'); if (ok) { setApproveWd(null); setWdRef(''); } };
  const rejectWithdrawal = async () => { const ok = await run(() => api(`/admin/withdrawals/${rejectWd.id}/reject`, { method: 'POST', body: { reason: wdReason } }), 'Levantamento rejeitado.'); if (ok) { setRejectWd(null); setWdReason(''); } };
  const resolve = async () => { const ok = await run(() => api(`/admin/reports/${resolveReport.id}/resolve`, { method: 'POST', body: { note: reportNote } }), 'Denúncia resolvida.'); if (ok) { setResolveReport(null); setReportNote(''); } };
  const saveSettings = async (e) => { e.preventDefault(); setSettingsBusy(true); try { const d = await api('/admin/settings', { method: 'PATCH', body: { commission: Number(settingsForm.commission), mpesaNumber: settingsForm.mpesaNumber, emolaNumber: settingsForm.emolaNumber, supportEmail: settingsForm.supportEmail, supportPhone: settingsForm.supportPhone, announcement: settingsForm.announcement } }); setSettings(d.settings); setSettingsForm(d.settings); await load(); toast('Definições guardadas.', 'success'); } catch (err) { toast(err.message, 'error'); } finally { setSettingsBusy(false); } };
  const addSubject = async (e) => { e.preventDefault(); const ok = await run(() => api('/admin/subjects', { method: 'POST', body: newSubject }), 'Disciplina adicionada.'); if (ok) setNewSubject({ name: '', icon: 'BookOpen' }); };
  const addLevel = async (e) => { e.preventDefault(); const ok = await run(() => api('/admin/levels', { method: 'POST', body: { name: newLevel } }), 'Nível adicionado.'); if (ok) setNewLevel(''); };
  const toggleSubject = (s) => run(() => api(`/admin/subjects/${s.id}`, { method: 'PATCH', body: { active: !s.active } }), s.active ? 'Disciplina desactivada.' : 'Disciplina activada.');
  const toggleLevel = (l) => run(() => api(`/admin/levels/${l.id}`, { method: 'PATCH', body: { active: !l.active } }), l.active ? 'Nível desactivado.' : 'Nível activado.');
  const seedDemo = async () => { setDemoBusy(true); try { const d = await api('/admin/demo-seed', { method: 'POST' }); setDemoResult(d); await load(); toast('Dados de demonstração criados.', 'success'); } catch (e) { toast(e.message, 'error'); } finally { setDemoBusy(false); } };
  const clearDemo = async () => { setDemoClearBusy(true); try { const d = await api('/admin/demo-clear', { method: 'POST' }); await load(); toast(d.removed ? 'Dados de demonstração removidos.' : 'Não havia dados de demonstração.', 'success'); setClearDemoOpen(false); } catch (e) { toast(e.message, 'error'); } finally { setDemoClearBusy(false); } };
  const sendNotification = async (e) => { e.preventDefault(); setNotifBusy(true); try { await api('/admin/notifications', { method: 'POST', body: { ...notifForm, userId: notifForm.userId || undefined } }); setNotifForm({ userId: '', title: '', body: '', link: '' }); toast('Notificação enviada.', 'success'); } catch (err) { toast(err.message, 'error'); } finally { setNotifBusy(false); } };
  const promote = async () => { setTeamBusy(true); try { await api('/admin/team/promote', { method: 'POST', body: { userId: promoteId } }); await load(); setPromoteId(''); toast('Administrador nomeado.', 'success'); } catch (e) { toast(e.message, 'error'); } finally { setTeamBusy(false); } };
  const demote = async (id) => { setTeamBusy(true); try { await api('/admin/team/demote', { method: 'POST', body: { userId: id } }); await load(); toast('Permissão de administrador removida.', 'success'); } catch (e) { toast(e.message, 'error'); } finally { setTeamBusy(false); } };
  const tabs = [
    { id: 'overview', label: 'Visão geral', icon: LayoutDashboard }, { id: 'applications', label: 'Candidaturas', icon: FileCheck2, count: stats?.counts.pendingApplications || 0 },
    { id: 'payments', label: 'Pagamentos', icon: CreditCard, count: stats?.counts.pendingPayments || 0 }, { id: 'lessons', label: 'Aulas', icon: BookOpen }, { id: 'bookings', label: 'Reservas', icon: CalendarDays },
    { id: 'users', label: 'Utilizadores', icon: Users }, { id: 'withdrawals', label: 'Levantamentos', icon: Wallet }, { id: 'reviews', label: 'Avaliações', icon: Star }, { id: 'reports', label: 'Denúncias', icon: Flag, count: stats?.counts.openReports || 0 },
    { id: 'catalog', label: 'Disciplinas e níveis', icon: Tags }, { id: 'settings', label: 'Definições', icon: SettingsIcon }, { id: 'notifications', label: 'Notificações', icon: Bell }, { id: 'audit', label: 'Auditoria', icon: ScrollText }, { id: 'team', label: 'Equipa', icon: ShieldCheck }
  ];
  const titles = { overview: ['Administração EDUCA', 'Estatísticas, pagamentos e atividade da plataforma.'], applications: ['Candidaturas de professor', 'Analisa documentos e aprova ou rejeita candidaturas.'], payments: ['Pagamentos', 'Confirma referências M-Pesa e e-Mola e processa reembolsos.'], lessons: ['Gestão de aulas', 'Todas as aulas publicadas na plataforma.'], bookings: ['Reservas', 'Histórico completo de reservas dos estudantes.'], users: ['Utilizadores', 'Contas, funções, suspensões e permissões.'], withdrawals: ['Levantamentos', 'Pedidos dos professores e decisões da administração.'], reviews: ['Avaliações', 'Moderação das avaliações públicas.'], reports: ['Denúncias', 'Reclamações de estudantes sobre professores ou avaliações.'], catalog: ['Disciplinas e níveis', 'Configuração do catálogo da plataforma.'], settings: ['Definições da plataforma', 'Comissão, números de pagamento, suporte e integrações.'], notifications: ['Notificações', 'Envia avisos a um utilizador ou a toda a plataforma.'], audit: ['Registos de auditoria', 'Atividade administrativa e eventos relevantes.'], team: ['Equipa de administração', 'Nomeia ou remove administradores. Apenas o proprietário.'], };
  if (loading) return <div className="container"><LoadingRow large /></div>;
  const pendingPayments = payments.filter(p => p.status === 'pending');
  const filteredApps = applications.filter(a => appFilter === 'all' || a.status === appFilter);
  const filteredPayments = payments.filter(p => payFilter === 'all' || p.status === payFilter);
  const filteredUsers = users.filter(u => (userRole === 'all' || u.role === userRole) && (userStatus === 'all' || u.status === userStatus) && (!userQuery || [u.name, u.email, u.phone].join(' ').toLowerCase().includes(userQuery.toLowerCase())));
  const filteredWithdrawals = withdrawals.filter(w => wdFilter === 'all' || w.status === wdFilter);
  return (
    <PanelShell title={titles[tab][0]} subtitle={titles[tab][1]} tabs={tabs} active={tab} onChange={setTab} actions={<div className="flex gap-8 wrap"><a className="btn btn-outline btn-sm" href="/api/admin/export/payments.csv"><Download size={14} /> Exportar CSV</a><span className="badge badge-green"><ShieldCheck size={12} /> {user?.name}</span></div>}>
      {tab === 'overview' && <div style={{ display: 'grid', gap: 18 }}>
        <div className="stat-grid"><div className="stat-card green"><div className="stat-label"><Users size={13} />Total de utilizadores</div><div className="stat-value">{formatNumber(stats?.counts.totalUsers || 0)}</div><div className="stat-note">{stats?.counts.students || 0} estudantes · {stats?.counts.teachers || 0} professores</div></div><div className="stat-card"><div className="stat-label"><TrendingUp size={13} />Receita confirmada</div><div className="stat-value">{formatMT(stats?.counts.revenue || 0)}</div><div className="stat-note">{stats?.counts.paidBookings || 0} reservas pagas</div></div><div className="stat-card orange"><div className="stat-label"><CreditCard size={13} />Pagamentos pendentes</div><div className="stat-value">{stats?.counts.pendingPayments || 0}</div><div className="stat-note">a aguardar verificação</div></div><div className="stat-card purple"><div className="stat-label"><FileCheck2 size={13} />Candidaturas</div><div className="stat-value">{stats?.counts.pendingApplications || 0}</div><div className="stat-note">por analisar</div></div></div>
        <div className="grid" style={{ gridTemplateColumns: '1.4fr .6fr', alignItems: 'start' }}>
          <div className="card chart-card"><div className="flex between align-center"><div><h3 style={{ fontSize: '.95rem' }}>Receita confirmada por mês</h3><span className="tiny muted">valores brutos das reservas pagas</span></div><Badge tone="green">MT</Badge></div><div className="bar-chart">{stats?.monthly?.length ? stats.monthly.map(m => <div className="bar-col" key={m.month}><span className="bar-value">{formatNumber(Math.round(m.revenue))}</span><div className="bar" style={{ height: `${Math.max(4, (m.revenue / Math.max(...stats.monthly.map(x => x.revenue), 1)) * 100)}%` }} /><span className="bar-label">{m.month}</span></div>) : <p className="small muted">Sem dados de receita confirmada.</p>}</div></div>
          <div className="card card-pad"><h3 style={{ fontSize: '.95rem' }}>Comissões e levantamentos</h3><div className="kv" style={{ marginTop: 8 }}><span>Comissão EDUCA</span><span>{formatMT(stats?.counts.commission || 0)}</span></div><div className="kv"><span>Levantamentos pendentes</span><span>{formatMT(stats?.counts.pendingPayouts || 0)}</span></div><div className="kv"><span>Denúncias abertas</span><span>{stats?.counts.openReports || 0}</span></div><div className="kv"><span>Contas suspensas</span><span>{stats?.counts.suspended || 0}</span></div><div className="notice notice-info" style={{ marginTop: 10 }}><ShieldCheck size={15} /><span>Confirma pagamentos apenas depois de verificares a referência no extracto.</span></div></div>
        </div>
        <div className="grid grid-2"><div className="card"><div className="card-pad" style={{ paddingBottom: 8 }}><div className="flex between align-center"><h3 style={{ fontSize: '.95rem' }}>Pagamentos por confirmar</h3><button className="link-arrow small" onClick={() => setTab('payments')}>Ver todos</button></div></div>{pendingPayments.slice(0, 5).map(p => <div key={p.id} className="flex between align-center gap-10" style={{ padding: '10px 24px', borderTop: '1px solid var(--line)' }}><div style={{ minWidth: 0 }}><strong style={{ fontSize: '.8rem', display: 'block' }}>{p.student_name} · {formatMT(p.amount)}</strong><span className="tiny muted">{p.lesson_title} · {p.reference || 'sem referência'}</span></div><div className="flex gap-6"><button className="btn btn-soft btn-sm" onClick={() => setConfirmPay(p)}>Confirmar</button><button className="icon-btn sm" onClick={() => setRejectPay(p)} aria-label="Rejeitar"><X size={13} /></button></div></div>)}{!pendingPayments.length && <p className="small muted" style={{ padding: '0 24px 20px' }}>Sem pagamentos pendentes.</p>}</div><div className="card"><div className="card-pad" style={{ paddingBottom: 8 }}><div className="flex between align-center"><h3 style={{ fontSize: '.95rem' }}>Candidaturas pendentes</h3><button className="link-arrow small" onClick={() => setTab('applications')}>Ver todas</button></div></div>{applications.filter(a => a.status === 'pending').slice(0, 5).map(a => <div key={a.id} className="flex between align-center gap-10" style={{ padding: '10px 24px', borderTop: '1px solid var(--line)' }}><div style={{ minWidth: 0 }}><strong style={{ fontSize: '.8rem', display: 'block' }}>{a.name}</strong><span className="tiny muted">{a.headline} · {a.city}</span></div><button className="btn btn-outline btn-sm" onClick={() => setAppDetail(a)}>Analisar</button></div>)}{!applications.filter(a => a.status === 'pending').length && <p className="small muted" style={{ padding: '0 24px 20px' }}>Sem candidaturas pendentes.</p>}</div></div>
        <div className="card"><div className="card-pad" style={{ paddingBottom: 8 }}><h3 style={{ fontSize: '.95rem' }}>Receita por disciplina</h3></div><div className="table-wrap" style={{ border: 0, borderRadius: 0 }}><table className="data-table"><thead><tr><th>Disciplina</th><th>Reservas</th><th>Receita</th><th>Comissão</th></tr></thead><tbody>{stats?.bySubject?.length ? stats.bySubject.map(s => <tr key={s.id}><td><strong style={{ fontSize: '.8rem' }}>{s.name}</strong></td><td>{s.bookings}</td><td>{formatMT(s.revenue)}</td><td>{formatMT(s.commission)}</td></tr>) : <tr><td colSpan={4} className="muted small">Sem receita confirmada.</td></tr>}</tbody></table></div></div>
      </div>}
      {tab === 'applications' && <div><div className="filter-bar" style={{ marginBottom: 14 }}>{['pending','approved','rejected','all'].map(s => <button key={s} className={`btn btn-sm ${appFilter === s ? 'btn-primary' : 'btn-outline'}`} onClick={() => setAppFilter(s)}>{s === 'all' ? 'Todas' : APPLICATION_LABELS[s]}</button>)}</div>{filteredApps.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Candidato</th><th>Contacto</th><th>Cidade</th><th>Preço</th><th>Disciplinas</th><th>Estado</th><th>Data</th><th>Acções</th></tr></thead><tbody>{filteredApps.map(a => <tr key={a.id}><td><div className="flex gap-8 align-center"><Avatar name={a.name} size="sm" /><div><strong style={{ fontSize: '.8rem' }}>{a.name}</strong><div className="tiny muted">{a.headline}</div></div></div></td><td className="tiny">{a.email}<br />{a.phone}</td><td>{a.city}</td><td>{formatMT(a.price)}</td><td className="tiny">{a.subjectNames?.join(', ')}</td><td><StatusBadge status={a.status} /></td><td className="tiny muted">{formatDate(a.created_at)}</td><td><div className="table-actions"><button className="btn btn-outline btn-sm" onClick={() => setAppDetail(a)}><Eye size={12} /> Ver</button>{a.status === 'pending' && <><button className="btn btn-soft btn-sm" onClick={() => approveApp(a.id)}><Check size={12} /> Aprovar</button><button className="icon-btn sm" onClick={() => { setRejectApp(a); setRejectReason(''); }} aria-label="Rejeitar"><X size={13} /></button></>}</div></td></tr>)}</tbody></table></div> : <EmptyState icon={FileCheck2} title="Sem candidaturas neste estado" description="As candidaturas de professor aparecem aqui para análise." />}</div>}
      {tab === 'payments' && <div><div className="flex between align-center wrap gap-10" style={{ marginBottom: 14 }}><div className="filter-bar">{['pending','confirmed','rejected','refunded','all'].map(s => <button key={s} className={`btn btn-sm ${payFilter === s ? 'btn-primary' : 'btn-outline'}`} onClick={() => setPayFilter(s)}>{s === 'all' ? 'Todos' : PAYMENT_LABELS[s]}</button>)}</div><a className="btn btn-outline btn-sm" href="/api/admin/export/payments.csv"><Download size={13} /> CSV</a></div>{(!settings?.mpesaNumber || !settings?.emolaNumber) && <div className="notice notice-warning" style={{ marginBottom: 14 }}><AlertCircle size={15} /><span>Os números de pagamento ainda não estão configurados. Configura-os em Definições antes de aceitar novas reservas.</span><button className="link-arrow" style={{ marginLeft: 'auto' }} onClick={() => setTab('settings')}>Configurar</button></div>}{filteredPayments.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Estudante</th><th>Aula</th><th>Professor</th><th>Método</th><th>Referência</th><th>Valor</th><th>Estado</th><th>Data</th><th>Acções</th></tr></thead><tbody>{filteredPayments.map(p => <tr key={p.id}><td><strong style={{ fontSize: '.8rem' }}>{p.student_name}</strong><div className="tiny muted">{p.student_phone}</div></td><td className="tiny">{p.lesson_title}<div className="tiny muted">{formatDate(p.start_at)} · {formatTime(p.start_at)}</div></td><td className="tiny">{p.teacher_name}</td><td>{p.method}</td><td className="tiny" style={{ fontWeight: 700 }}>{p.reference || '—'}</td><td>{formatMT(p.amount)}</td><td><StatusBadge status={p.status} /></td><td className="tiny muted">{formatDate(p.created_at)}</td><td><div className="table-actions">{p.status === 'pending' && <><button className="btn btn-soft btn-sm" onClick={() => { setConfirmPay(p); setAttested(false); setPayNote(''); }}><Check size={12} /> Confirmar</button><button className="icon-btn sm" onClick={() => { setRejectPay(p); setPayReason(''); }} aria-label="Rejeitar"><X size={13} /></button></>}{p.status === 'confirmed' && <button className="btn btn-outline btn-sm" onClick={() => { setRefundPay(p); setRefundReason(''); }}><RotateCcw size={12} /> Reembolsar</button>}</div></td></tr>)}</tbody></table></div> : <EmptyState icon={CreditCard} title="Sem pagamentos neste estado" description="Os pagamentos submetidos pelos estudantes aparecem aqui." />}</div>}
      {tab === 'lessons' && (lessons.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Aula</th><th>Professor</th><th>Data</th><th>Formato</th><th>Lugares</th><th>Preço</th><th>Estado</th><th>Acções</th></tr></thead><tbody>{lessons.map(l => <tr key={l.id}><td><strong style={{ fontSize: '.8rem' }}>{l.title}</strong><div className="tiny muted">{l.subject_name} · {l.level_name}</div></td><td className="tiny">{l.teacher_name}</td><td className="tiny">{formatDate(l.start_at)}<br />{formatTime(l.start_at)}</td><td>{l.mode === 'individual' ? 'Individual' : 'Grupo'}</td><td>{l.taken}/{l.seats}</td><td>{formatMT(l.price)}</td><td><StatusBadge status={l.status} /></td><td><div className="table-actions">{l.status === 'published' && <><button className="icon-btn sm" onClick={() => setCompleteLesson(l)} aria-label="Concluir"><Check size={13} /></button><button className="icon-btn sm" onClick={() => setCancelLesson(l)} aria-label="Cancelar"><X size={13} /></button></>}<Link to={`/aula/${l.id}`} className="icon-btn sm" aria-label="Ver"><Eye size={13} /></Link></div></td></tr>)}</tbody></table></div> : <EmptyState icon={BookOpen} title="Sem aulas" description="Ainda não há aulas publicadas." />)}
      {tab === 'bookings' && (bookings.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Estudante</th><th>Aula</th><th>Professor</th><th>Valor</th><th>Reserva</th><th>Pagamento</th><th>Data</th></tr></thead><tbody>{bookings.map(b => <tr key={b.id}><td><strong style={{ fontSize: '.8rem' }}>{b.student_name}</strong><div className="tiny muted">{b.student_email}</div></td><td className="tiny">{b.lesson_title}</td><td className="tiny">{b.teacher_name}</td><td>{formatMT(b.amount)}</td><td><StatusBadge status={b.status} /></td><td><StatusBadge status={b.payment_status} /></td><td className="tiny muted">{formatDate(b.created_at)}</td></tr>)}</tbody></table></div> : <EmptyState icon={CalendarDays} title="Sem reservas" description="As reservas dos estudantes aparecem aqui." />)}
      {tab === 'users' && <div><div className="filter-bar" style={{ marginBottom: 14 }}><div className="input flex align-center gap-8" style={{ minWidth: 220 }}><Search size={14} style={{ color: 'var(--muted)' }} /><input className="input" style={{ border: 0, padding: 0, background: 'transparent' }} placeholder="Nome, email ou telefone" value={userQuery} onChange={e => setUserQuery(e.target.value)} /></div><select className="select" style={{ width: 'auto' }} value={userRole} onChange={e => setUserRole(e.target.value)}><option value="all">Todas as funções</option><option value="student">Estudantes</option><option value="teacher">Professores</option><option value="admin">Administradores</option></select><select className="select" style={{ width: 'auto' }} value={userStatus} onChange={e => setUserStatus(e.target.value)}><option value="all">Todos os estados</option><option value="active">Activos</option><option value="suspended">Suspensos</option></select></div>{filteredUsers.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Utilizador</th><th>Função</th><th>Estado</th><th>Candidatura</th><th>Registo</th><th>Acções</th></tr></thead><tbody>{filteredUsers.map(u => <tr key={u.id}><td><div className="flex gap-8 align-center"><Avatar name={u.name} src={u.avatar_file_id ? `/api/files/${u.avatar_file_id}` : null} size="sm" /><div><strong style={{ fontSize: '.8rem' }}>{u.name} {u.is_owner ? <Badge tone="orange">Proprietário</Badge> : null}{u.demo ? <Badge tone="gray">Demo</Badge> : null}</strong><div className="tiny muted">{u.email}</div></div></div></td><td><Badge tone={u.role === 'admin' ? 'purple' : u.role === 'teacher' ? 'green' : 'gray'}>{u.role === 'admin' ? 'Administrador' : u.role === 'teacher' ? 'Professor' : 'Estudante'}</Badge></td><td><StatusBadge status={u.status} /></td><td className="tiny">{u.application_status ? APPLICATION_LABELS[u.application_status] : '—'}</td><td className="tiny muted">{formatDate(u.created_at)}</td><td><div className="table-actions">{u.status === 'active' ? <button className="btn btn-outline btn-sm" onClick={() => { setSuspendUser(u); setSuspendReason(''); }}>Suspender</button> : <button className="btn btn-soft btn-sm" onClick={() => reactivate(u.id)}>Reactivar</button>}{u.status === 'suspended' && u.role === 'admin' && <button className="btn btn-outline btn-sm" onClick={() => reactivate(u.id)}>Reactivar</button>}</div></td></tr>)}</tbody></table></div> : <EmptyState icon={Users} title="Sem utilizadores" description="Ajusta a pesquisa ou os filtros." />}</div>}
      {tab === 'withdrawals' && <div><div className="filter-bar" style={{ marginBottom: 14 }}>{['all','pending','paid','rejected'].map(s => <button key={s} className={`btn btn-sm ${wdFilter === s ? 'btn-primary' : 'btn-outline'}`} onClick={() => setWdFilter(s)}>{s === 'all' ? 'Todos' : s === 'pending' ? 'Pendentes' : s === 'paid' ? 'Pagos' : 'Rejeitados'}</button>)}</div>{filteredWithdrawals.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Professor</th><th>Valor</th><th>Método</th><th>Número</th><th>Estado</th><th>Pedido</th><th>Acções</th></tr></thead><tbody>{filteredWithdrawals.map(w => <tr key={w.id}><td><strong style={{ fontSize: '.8rem' }}>{w.teacher_name}</strong><div className="tiny muted">{w.teacher_email}</div></td><td>{formatMT(w.amount)}</td><td>{w.method}</td><td className="tiny">{w.number}</td><td><StatusBadge status={w.status} /></td><td className="tiny muted">{formatDate(w.requested_at)}</td><td><div className="table-actions">{w.status === 'pending' && <><button className="btn btn-soft btn-sm" onClick={() => { setApproveWd(w); setWdRef(''); }}><Check size={12} /> Aprovar</button><button className="icon-btn sm" onClick={() => { setRejectWd(w); setWdReason(''); }} aria-label="Rejeitar"><X size={13} /></button></>}{w.status === 'paid' && w.reference && <span className="tiny muted">Ref.: {w.reference}</span>}</div></td></tr>)}</tbody></table></div> : <EmptyState icon={Wallet} title="Sem levantamentos" description="Os pedidos dos professores aparecem aqui." />}</div>}
      {tab === 'reviews' && (reviews.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Professor</th><th>Estudante</th><th>Aula</th><th>Avaliação</th><th>Comentário</th><th>Estado</th><th>Acções</th></tr></thead><tbody>{reviews.map(r => <tr key={r.id}><td className="tiny">{r.teacher_name}</td><td className="tiny">{r.student_name}</td><td className="tiny">{r.lesson_title}</td><td>{r.rating ? <Stars value={r.rating} /> : '—'}</td><td className="tiny" style={{ maxWidth: 260 }}>{r.comment || '—'}</td><td><StatusBadge status={r.status} /></td><td><div className="table-actions">{r.status === 'visible' ? <button className="btn btn-outline btn-sm" onClick={() => run(() => api(`/admin/reviews/${r.id}/hide`, { method: 'POST' }), 'Avaliação ocultada.')}>Ocultar</button> : <button className="btn btn-soft btn-sm" onClick={() => run(() => api(`/admin/reviews/${r.id}/show`, { method: 'POST' }), 'Avaliação visível.')}>Mostrar</button>}</div></td></tr>)}</tbody></table></div> : <EmptyState icon={Star} title="Sem avaliações" description="As avaliações aparecem aqui depois de aulas concluídas." />)}
      {tab === 'reports' && (reports.length ? <div className="grid" style={{ gap: 12 }}>{reports.map(r => <div key={r.id} className="card card-pad"><div className="flex between align-center wrap gap-8"><div><strong style={{ fontSize: '.85rem' }}>{r.reason} · {r.target_name}</strong><div className="tiny muted">Denunciado por {r.reporter_name} ({r.reporter_email}) em {formatDateTime(r.created_at)}</div></div><StatusBadge status={r.status} /></div><p className="small" style={{ marginTop: 8 }}>{r.details || 'Sem detalhes adicionais.'}</p>{r.resolution_note && <div className="notice notice-info" style={{ marginTop: 8 }}><CheckCircle2 size={15} /><span>{r.resolution_note}</span></div>}{r.status === 'open' && <button className="btn btn-primary btn-sm" style={{ marginTop: 10 }} onClick={() => { setResolveReport(r); setReportNote(''); }}>Resolver denúncia</button>}</div>)}</div> : <EmptyState icon={Flag} title="Sem denúncias" description="As denúncias de estudantes aparecem aqui." />)}
      {tab === 'catalog' && <div className="grid grid-2" style={{ alignItems: 'start' }}><div className="card card-pad"><h3 style={{ fontSize: '.95rem' }}>Disciplinas</h3><form onSubmit={addSubject} className="flex gap-8" style={{ marginTop: 10 }}><input className="input" placeholder="Nova disciplina" value={newSubject.name} onChange={e => setNewSubject(s => ({ ...s, name: e.target.value }))} required /><button className="btn btn-primary btn-sm"><Plus size={14} /></button></form><div className="detail-list" style={{ marginTop: 12 }}>{subjects.map(s => <div key={s.id} className="detail-list-item"><div className="grow"><strong>{s.name}</strong><span>{s.slug}</span></div><button className={`btn btn-sm ${s.active ? 'btn-outline' : 'btn-soft'}`} onClick={() => toggleSubject(s)}>{s.active ? 'Desactivar' : 'Activar'}</button></div>)}</div></div><div className="card card-pad"><h3 style={{ fontSize: '.95rem' }}>Níveis de ensino</h3><form onSubmit={addLevel} className="flex gap-8" style={{ marginTop: 10 }}><input className="input" placeholder="Novo nível" value={newLevel} onChange={e => setNewLevel(e.target.value)} required /><button className="btn btn-primary btn-sm"><Plus size={14} /></button></form><div className="detail-list" style={{ marginTop: 12 }}>{levels.map(l => <div key={l.id} className="detail-list-item"><div className="grow"><strong>{l.name}</strong><span>{l.slug}</span></div><button className={`btn btn-sm ${l.active ? 'btn-outline' : 'btn-soft'}`} onClick={() => toggleLevel(l)}>{l.active ? 'Desactivar' : 'Activar'}</button></div>)}</div></div></div>}
      {tab === 'settings' && settingsForm && <div className="grid grid-2" style={{ alignItems: 'start' }}><form onSubmit={saveSettings} className="card card-pad"><h3 style={{ fontSize: '.95rem' }}>Pagamentos e comissão</h3><div className="grid gap-12" style={{ marginTop: 12 }}><div className="form-grid"><Field label="Comissão EDUCA (%)"><input className="input" type="number" min="0" max="50" step="0.5" value={settingsForm.commission} onChange={e => setSettingsForm(f => ({ ...f, commission: e.target.value }))} required /></Field><Field label="Número M-Pesa"><input className="input" value={settingsForm.mpesaNumber || ''} onChange={e => setSettingsForm(f => ({ ...f, mpesaNumber: e.target.value }))} placeholder="Ex.: 84 000 0000" /></Field><Field label="Número e-Mola"><input className="input" value={settingsForm.emolaNumber || ''} onChange={e => setSettingsForm(f => ({ ...f, emolaNumber: e.target.value }))} placeholder="Ex.: 86 000 0000" /></Field><Field label="Email de suporte"><input className="input" type="email" value={settingsForm.supportEmail || ''} onChange={e => setSettingsForm(f => ({ ...f, supportEmail: e.target.value }))} /></Field><Field label="Telefone de suporte"><input className="input" value={settingsForm.supportPhone || ''} onChange={e => setSettingsForm(f => ({ ...f, supportPhone: e.target.value }))} /></Field><div className="full"><Field label="Anúncio no topo do site"><input className="input" value={settingsForm.announcement || ''} onChange={e => setSettingsForm(f => ({ ...f, announcement: e.target.value }))} placeholder="Ex.: Novas aulas de preparação para exames." maxLength={500} /></Field></div></div></div><button className="btn btn-primary" style={{ marginTop: 12 }} disabled={settingsBusy}><CheckCircle2 size={15} /> Guardar definições</button></form><div style={{ display: 'grid', gap: 16 }}><div className="card card-pad"><h3 style={{ fontSize: '.95rem' }}>Estado das integrações</h3><div className="kv" style={{ marginTop: 8 }}><span>M-Pesa</span><span>Manual · confirmação pela equipa</span></div><div className="kv"><span>e-Mola</span><span>Manual · confirmação pela equipa</span></div><div className="kv"><span>Aulas ao vivo</span><span>{settings?.provider === 'jaas' ? 'JaaS com token' : 'Jitsi público (iframe)'}</span></div><div className="kv"><span>Email transaccional</span><span>{settings?.emailConfigured ? 'Configurado' : 'Não configurado (links de demonstração)'}</span></div><div className="notice notice-warning" style={{ marginTop: 10 }}><AlertCircle size={15} /><span>Os pagamentos automáticos exigem contrato de comerciante e credenciais oficiais. A plataforma está preparada para essa integração futura.</span></div></div><div className="card card-pad"><h3 style={{ fontSize: '.95rem' }}>Dados de demonstração</h3><p className="small muted" style={{ marginTop: 4 }}>Cria um professor, um estudante, aulas, uma reserva pendente, uma reserva confirmada, avaliação e conversa. Os dados são claramente identificados como demonstração.</p><button className="btn btn-outline btn-block" style={{ marginTop: 10 }} onClick={seedDemo} disabled={demoBusy}><Sparkles size={14} /> {demoBusy ? 'A criar…' : 'Carregar dados de demonstração'}</button><button className="btn btn-ghost btn-block btn-sm" style={{ marginTop: 6 }} onClick={() => setClearDemoOpen(true)} disabled={demoClearBusy}>Limpar dados de demonstração</button>{demoResult && <div className="notice notice-success" style={{ marginTop: 10 }}><CheckCircle2 size={15} /><span>Dados criados. As credenciais estão no painel. Configura os números de pagamento antes de confirmar a reserva pendente.</span></div>}</div><div className="card card-pad"><h3 style={{ fontSize: '.95rem' }}>Variáveis de ambiente</h3><div className="tiny muted" style={{ marginTop: 6, lineHeight: 1.8 }}><div><strong>ADMIN_EMAIL</strong> / <strong>ADMIN_PASSWORD</strong> — proprietário inicial</div><div><strong>RESEND_API_KEY</strong> / <strong>MAIL_FROM</strong> — email transaccional</div><div><strong>JITSI_JAAS_DOMAIN</strong>, <strong>JITSI_JAAS_KID</strong>, <strong>JITSI_JAAS_PRIVATE_KEY</strong> — vídeo com token</div><div><strong>COOKIE_SECURE=true</strong> — cookies seguros em produção</div><div><strong>EXPOSE_DEV_LINKS=true</strong> — mostra links de verificação/reposição</div></div></div></div></div>}
      {tab === 'notifications' && <div className="card card-pad" style={{ maxWidth: 720 }}><h3 style={{ fontSize: '.95rem' }}>Enviar notificação</h3><p className="help" style={{ marginTop: 3 }}>A notificação aparece no painel do utilizador e na página de notificações. Não envia email nem push.</p><form onSubmit={sendNotification} className="grid gap-12" style={{ marginTop: 12 }}><Field label="Destinatário"><select className="select" value={notifForm.userId} onChange={e => setNotifForm(f => ({ ...f, userId: e.target.value }))}><option value="">Todos os utilizadores activos</option>{users.filter(u => u.status === 'active').map(u => <option key={u.id} value={u.id}>{u.name} · {u.email}</option>)}</select></Field><Field label="Título"><input className="input" value={notifForm.title} onChange={e => setNotifForm(f => ({ ...f, title: e.target.value }))} placeholder="Ex.: Manutenção programada" required minLength={3} maxLength={120} /></Field><Field label="Mensagem"><textarea className="textarea" value={notifForm.body} onChange={e => setNotifForm(f => ({ ...f, body: e.target.value }))} placeholder="Escreve a mensagem…" required minLength={3} maxLength={1000} /></Field><Field label="Link (opcional)"><input className="input" value={notifForm.link} onChange={e => setNotifForm(f => ({ ...f, link: e.target.value }))} placeholder="Ex.: /aulas" /></Field><button className="btn btn-primary" disabled={notifBusy}><Bell size={15} /> Enviar notificação</button></form></div>}
      {tab === 'audit' && (audit.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Data</th><th>Actor</th><th>Acção</th><th>Entidade</th><th>Detalhes</th></tr></thead><tbody>{audit.map(a => <tr key={a.id}><td className="tiny muted">{formatDateTime(a.created_at)}</td><td className="tiny">{a.actor_name}</td><td><Badge tone="gray">{a.action}</Badge></td><td className="tiny">{a.entity_type}{a.entity_id ? ` · ${a.entity_id}` : ''}</td><td className="tiny muted" style={{ maxWidth: 280, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{a.details || '—'}</td></tr>)}</tbody></table></div> : <EmptyState icon={ScrollText} title="Sem registos" description="As ações administrativas são registadas aqui." />)}
      {tab === 'team' && <div className="grid grid-2" style={{ alignItems: 'start' }}><div className="card card-pad"><h3 style={{ fontSize: '.95rem' }}>Equipa de administração</h3><p className="help" style={{ marginTop: 3 }}>Apenas o proprietário pode nomear ou remover administradores. A permissão nunca é escolhida no registo público.</p><div className="detail-list" style={{ marginTop: 12 }}>{team.map(t => <div key={t.id} className="detail-list-item"><div className="grow"><strong>{t.name} {t.id === user?.id ? <Badge tone="green">tu</Badge> : null}</strong><span>{t.email} · {t.id}</span></div>{user?.isOwner && t.id !== user?.id && <button className="btn btn-outline btn-sm" onClick={() => demote(t.id)} disabled={teamBusy}><UserMinus size={12} /> Remover</button>}</div>)}</div>{user?.isOwner && <><div className="divider" /><h4 style={{ fontSize: '.85rem' }}>Nomear administrador</h4><p className="help">Cola o identificador de conta do utilizador. A pessoa deve ter sessão iniciada na plataforma.</p><div className="flex gap-8" style={{ marginTop: 8 }}><input className="input" placeholder="ID da conta (usr_…)" value={promoteId} onChange={e => setPromoteId(e.target.value)} /><button className="btn btn-primary" onClick={promote} disabled={teamBusy || !promoteId}><UserPlus size={14} /> Nomear</button></div></>}{!user?.isOwner && <div className="notice notice-info" style={{ marginTop: 10 }}><Lock size={15} /><span>Apenas o proprietário da plataforma pode gerir a equipa de administração.</span></div>}</div><div className="card card-pad"><h3 style={{ fontSize: '.95rem' }}>Conta do proprietário</h3><div className="kv" style={{ marginTop: 8 }}><span>Nome</span><span>{user?.name}</span></div><div className="kv"><span>Email</span><span>{user?.email}</span></div><div className="kv"><span>Identificador</span><span className="tiny">{user?.id}</span></div><div className="kv"><span>Permissão</span><span><Badge tone="orange">Proprietário</Badge></span></div><div className="notice notice-info" style={{ marginTop: 10 }}><ShieldCheck size={15} /><span>O proprietário é administrador por definição. Não pode ser suspenso nem removido da equipa.</span></div></div></div>}
      <Modal open={!!appDetail} onClose={() => setAppDetail(null)} title={appDetail?.name} subtitle="Candidatura a professor" wide footer={appDetail ? <>{appDetail.status === 'pending' && <><button className="btn btn-danger" onClick={() => { setRejectApp(appDetail); setRejectReason(''); }}><X size={14} /> Rejeitar</button><button className="btn btn-primary" onClick={() => approveApp(appDetail.id)} disabled={busy}><Check size={14} /> Aprovar candidatura</button></>}<button className="btn btn-ghost" onClick={() => setAppDetail(null)}>Fechar</button></> : null}>
        {appDetail && <div className="grid grid-2" style={{ gap: 16 }}><div><div className="kv"><span>Estado</span><span><StatusBadge status={appDetail.status} /></span></div><div className="kv"><span>Email</span><span>{appDetail.email}</span></div><div className="kv"><span>Telefone</span><span>{appDetail.phone}</span></div><div className="kv"><span>Cidade</span><span>{appDetail.city}</span></div><div className="kv"><span>Preço</span><span>{formatMT(appDetail.price)}</span></div><div className="kv"><span>Submetida</span><span>{formatDateTime(appDetail.created_at)}</span></div><div className="kv"><span>Disciplinas</span><span>{appDetail.subjectNames?.join(', ')}</span></div><div className="kv"><span>Níveis</span><span>{appDetail.levelNames?.join(', ')}</span></div></div><div><h4 style={{ fontSize: '.85rem' }}>Apresentação</h4><p className="small" style={{ marginTop: 4 }}>{appDetail.bio}</p><h4 style={{ fontSize: '.85rem', marginTop: 12 }}>Documentos</h4>{appDetail.documents?.length ? appDetail.documents.map(d => <a key={d.id} href={`/api/files/${d.file_id}`} target="_blank" rel="noreferrer" className="btn btn-outline btn-sm btn-block" style={{ marginTop: 6 }}><Eye size={12} /> {d.kind} · {d.filename}</a>) : <p className="small muted">Sem documentos carregados.</p>}{appDetail.rejection_reason && <div className="notice notice-danger" style={{ marginTop: 10 }}><AlertCircle size={15} /><span>{appDetail.rejection_reason}</span></div>}</div></div>}
      </Modal>
      <Modal open={!!rejectApp} onClose={() => setRejectApp(null)} title="Rejeitar candidatura" subtitle={rejectApp?.name} footer={<><button className="btn btn-ghost" onClick={() => setRejectApp(null)}>Cancelar</button><button className="btn btn-danger" onClick={doRejectApp} disabled={busy || rejectReason.trim().length < 5}>Rejeitar</button></>}><Field label="Motivo da rejeição" help="O candidato vê este motivo. Mínimo 5 caracteres."><textarea className="textarea" value={rejectReason} onChange={e => setRejectReason(e.target.value)} placeholder="Ex.: documentação incompleta…" /></Field></Modal>
      <Modal open={!!confirmPay} onClose={() => setConfirmPay(null)} title="Confirmar pagamento" subtitle={confirmPay ? `${confirmPay.student_name} · ${formatMT(confirmPay.amount)}` : ''} footer={<><button className="btn btn-ghost" onClick={() => setConfirmPay(null)}>Cancelar</button><button className="btn btn-primary" onClick={confirmPayment} disabled={busy || !attested}><Check size={14} /> Confirmar pagamento</button></>}>{confirmPay && <><div className="card card-pad" style={{ background: 'var(--cream)', marginBottom: 12 }}><div className="flex between align-center"><span className="small muted">Referência</span><strong>{confirmPay.reference || '—'}</strong></div><div className="flex between align-center" style={{ marginTop: 6 }}><span className="small muted">Método</span><strong>{confirmPay.method}</strong></div><div className="flex between align-center" style={{ marginTop: 6 }}><span className="small muted">Aula</span><strong style={{ fontSize: '.8rem' }}>{confirmPay.lesson_title}</strong></div><div className="flex between align-center" style={{ marginTop: 6 }}><span className="small muted">Professor</span><strong style={{ fontSize: '.8rem' }}>{confirmPay.teacher_name}</strong></div></div><div className="notice notice-warning" style={{ marginBottom: 12 }}><AlertCircle size={15} /><span>Confirma no extracto M-Pesa/e-Mola que a referência existe e corresponde ao valor. A confirmação credita a carteira do professor e autoriza a sala.</span></div><label className="checkbox"><input type="checkbox" checked={attested} onChange={e => setAttested(e.target.checked)} /><span>Confirmo que verifiquei esta referência no extracto oficial.</span></label><Field label="Nota interna (opcional)"><input className="input" value={payNote} onChange={e => setPayNote(e.target.value)} placeholder="Ex.: verificado no extracto das 14h" /></Field></>}</Modal>
      <Modal open={!!rejectPay} onClose={() => setRejectPay(null)} title="Rejeitar pagamento" subtitle={rejectPay?.student_name} footer={<><button className="btn btn-ghost" onClick={() => setRejectPay(null)}>Cancelar</button><button className="btn btn-danger" onClick={rejectPayment} disabled={busy || payReason.trim().length < 5}>Rejeitar pagamento</button></>}><Field label="Motivo" help="O estudante é notificado e pode submeter uma nova referência."><textarea className="textarea" value={payReason} onChange={e => setPayReason(e.target.value)} placeholder="Ex.: referência não encontrada no extracto…" /></Field></Modal>
      <Modal open={!!refundPay} onClose={() => setRefundPay(null)} title="Reembolsar pagamento" subtitle={refundPay ? `${refundPay.student_name} · ${formatMT(refundPay.amount)}` : ''} footer={<><button className="btn btn-ghost" onClick={() => setRefundPay(null)}>Cancelar</button><button className="btn btn-danger" onClick={refundPayment} disabled={busy || refundReason.trim().length < 5}>Confirmar reembolso</button></>}><div className="notice notice-danger" style={{ marginBottom: 12 }}><AlertCircle size={15} /><span>O reembolso fecha a sala, oculta a avaliação e cria um movimento negativo na carteira do professor. A transferência real é feita pela equipa.</span></div><Field label="Motivo do reembolso"><textarea className="textarea" value={refundReason} onChange={e => setRefundReason(e.target.value)} placeholder="Ex.: aula cancelada pelo professor…" /></Field></Modal>
      <Modal open={!!cancelLesson} onClose={() => setCancelLesson(null)} title="Cancelar aula" subtitle={cancelLesson?.title} footer={<><button className="btn btn-ghost" onClick={() => setCancelLesson(null)}>Cancelar</button><button className="btn btn-danger" onClick={doCancelLesson} disabled={busy}>Cancelar aula</button></>}><p className="small muted">As reservas pendentes serão canceladas. As reservas pagas ficam para reembolso. A sala deixa de estar acessível.</p></Modal>
      <Modal open={!!completeLesson} onClose={() => setCompleteLesson(null)} title="Marcar aula como concluída" subtitle={completeLesson?.title} footer={<><button className="btn btn-ghost" onClick={() => setCompleteLesson(null)}>Cancelar</button><button className="btn btn-primary" onClick={doCompleteLesson} disabled={busy}>Concluir aula</button></>}><p className="small muted">Os estudantes com pagamento confirmado poderão avaliar o professor.</p></Modal>
      <Modal open={!!suspendUser} onClose={() => setSuspendUser(null)} title="Suspender conta" subtitle={suspendUser?.name} footer={<><button className="btn btn-ghost" onClick={() => setSuspendUser(null)}>Cancelar</button><button className="btn btn-danger" onClick={suspend} disabled={busy || suspendReason.trim().length < 5}>Suspender conta</button></>}><Field label="Motivo"><textarea className="textarea" value={suspendReason} onChange={e => setSuspendReason(e.target.value)} placeholder="Ex.: violação dos termos de utilização…" /></Field><div className="notice notice-warning" style={{ marginTop: 10 }}><AlertCircle size={15} /><span>A conta perde imediatamente a sessão. O proprietário não pode ser suspenso.</span></div></Modal>
      <Modal open={!!approveWd} onClose={() => setApproveWd(null)} title="Aprovar levantamento" subtitle={approveWd ? `${approveWd.teacher_name} · ${formatMT(approveWd.amount)}` : ''} footer={<><button className="btn btn-ghost" onClick={() => setApproveWd(null)}>Cancelar</button><button className="btn btn-primary" onClick={approveWithdrawal} disabled={busy || wdRef.trim().length < 3}>Aprovar pagamento</button></>}><Field label="Referência da transferência" help="Regista a referência M-Pesa/e-Mola usada para pagar o professor."><input className="input" value={wdRef} onChange={e => setWdRef(e.target.value)} placeholder="Ex.: MP2024XYZ" /></Field></Modal>
      <Modal open={!!rejectWd} onClose={() => setRejectWd(null)} title="Rejeitar levantamento" subtitle={rejectWd?.teacher_name} footer={<><button className="btn btn-ghost" onClick={() => setRejectWd(null)}>Cancelar</button><button className="btn btn-danger" onClick={rejectWithdrawal} disabled={busy || wdReason.trim().length < 5}>Rejeitar</button></>}><Field label="Motivo"><textarea className="textarea" value={wdReason} onChange={e => setWdReason(e.target.value)} /></Field></Modal>
      <Modal open={!!resolveReport} onClose={() => setResolveReport(null)} title="Resolver denúncia" subtitle={resolveReport?.target_name} footer={<><button className="btn btn-ghost" onClick={() => setResolveReport(null)}>Cancelar</button><button className="btn btn-primary" onClick={resolve} disabled={busy}>Resolver</button></>}><Field label="Nota de resolução"><textarea className="textarea" value={reportNote} onChange={e => setReportNote(e.target.value)} placeholder="O que foi decidido…" /></Field></Modal>
      <Modal open={clearDemoOpen} onClose={() => setClearDemoOpen(false)} title="Limpar dados de demonstração" subtitle="Remove as contas demo.professor@educa.mz e demo.estudante@educa.mz e todos os dados associados." footer={<><button className="btn btn-ghost" onClick={() => setClearDemoOpen(false)}>Cancelar</button><button className="btn btn-danger" onClick={clearDemo} disabled={demoClearBusy}>Limpar dados</button></>}><div className="notice notice-warning"><AlertCircle size={15} /><span>Esta ação remove o professor, o estudante, aulas, reservas, pagamentos, avaliação, conversa e notificações de demonstração. As contas reais não são afetadas.</span></div></Modal>
      {demoResult && <Modal open={!!demoResult} onClose={() => setDemoResult(null)} title="Dados de demonstração" subtitle="Credenciais para testar os três painéis" footer={<button className="btn btn-primary" onClick={() => setDemoResult(null)}>Fechar</button>}><div className="notice notice-success" style={{ marginBottom: 12 }}><CheckCircle2 size={15} /><span>{demoResult.note || 'Dados de demonstração criados.'}</span></div><div className="grid gap-8">{Object.entries(demoResult.credentials || {}).map(([role, c]) => <div key={role} className="card card-pad" style={{ padding: 12 }}><strong style={{ fontSize: '.8rem', textTransform: 'capitalize' }}>{role}</strong><div className="tiny muted">{c.email}</div><div className="tiny">Palavra-passe: <strong>{c.password}</strong></div></div>)}</div></Modal>}
    </PanelShell>
  );
}
